#include "poi/PoiKitPlacement.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::poi{namespace{std::uint64_t mix(std::uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}std::uint64_t hash(std::uint64_t a,std::uint64_t b,std::uint64_t c,std::uint64_t d){return mix(a^mix(b)^mix(c)^mix(d));}double unit(std::uint64_t h){return static_cast<double>(h>>11)*(1.0/9007199254740992.0);}}
bool PoiKitPlacementGenerator::publish(PoiKitDef k){if(!k.contentId||!k.factionGrammarContentId||!k.locationCompatibilityMask||k.modules.empty())return false;std::sort(k.modules.begin(),k.modules.end(),[](auto&a,auto&b){return a.contentId<b.contentId;});for(auto&m:k.modules){if(!m.contentId||!std::isfinite(m.inclusionProbability)||m.inclusionProbability<0||m.inclusionProbability>1)return false;}for(std::size_t i=1;i<k.modules.size();++i)if(k.modules[i-1].contentId==k.modules[i].contentId)return false;kits_[k.contentId]=std::move(k);return true;}
PoiKitPlacement PoiKitPlacementGenerator::generate(std::uint64_t id,const PoiPlacementKey&k,const PoiKitPersistentState&p,std::uint32_t requestedWorkerCount)const{(void)requestedWorkerCount;PoiKitPlacement o;auto i=kits_.find(id);if(i==kits_.end()||!k.worldSeed||!k.worldId||!k.spatialAddress||!k.generatorVersion)return o;const auto base=hash(k.worldSeed,k.worldId,k.spatialAddress,k.generatorVersion^id);o.kitContentId=id;o.placementStableId=hash(base,id,0x504f49ULL,k.generatorVersion);o.encounterSeed=hash(base,id,0x454e43ULL,k.generatorVersion);o.orientationQuarterTurns=static_cast<std::uint32_t>(base&3ULL);for(const auto&m:i->second.modules){const auto h=hash(base,m.contentId,i->second.factionGrammarContentId,k.generatorVersion);if(!m.required&&unit(h)>m.inclusionProbability)continue;const auto oid=hash(o.placementStableId,m.contentId,0x4d4f44ULL,k.generatorVersion);if(p.tombstonedObjectIds.contains(oid))continue;std::uint32_t dmg=static_cast<std::uint32_t>((h>>16)%451ULL);auto di=p.addedDamagePermille.find(oid);if(di!=p.addedDamagePermille.end())dmg=elysium::safe::saturatingAdd(dmg,di->second);dmg=std::min<std::uint32_t>(1000,dmg);o.modules.push_back({oid,m.contentId,m.role,static_cast<std::uint32_t>((h>>8)&3ULL),dmg,static_cast<std::uint32_t>((h>>32)&0xffffULL)});}std::sort(o.modules.begin(),o.modules.end(),[](auto&a,auto&b){return a.stableObjectId<b.stableObjectId;});return o;}
} // namespace elysium::poi
